// Generates generated/tokens.css and generated/tokens.ts from tokens.json.
//   node build-tokens.ts           write the generated files
//   node build-tokens.ts --check   exit 1 if the committed files are stale
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as prettier from 'prettier';

export const THEMES = ['light', 'dark'] as const;
export type Theme = (typeof THEMES)[number];

export interface TokenSource {
  themed: Record<string, Record<Theme, string>>;
  static: Record<string, string>;
}

export interface GeneratedFile {
  path: string;
  content: string;
}

const PACKAGE_DIR = dirname(fileURLToPath(import.meta.url));
export const SOURCE_PATH = join(PACKAGE_DIR, 'tokens.json');
export const CSS_PATH = join(PACKAGE_DIR, 'generated', 'tokens.css');
export const TS_PATH = join(PACKAGE_DIR, 'generated', 'tokens.ts');

const TOKEN_NAME = /^[a-z][a-z0-9]*(-[a-z0-9]+)*$/;
const HEADER = 'Generated by packages/design-tokens/build-tokens.ts from tokens.json. Do not edit.';

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function assertTokenName(name: string, seen: Set<string>): void {
  if (!TOKEN_NAME.test(name)) throw new Error(`invalid token name "${name}"`);
  if (seen.has(name)) throw new Error(`duplicate token name "${name}"`);
  seen.add(name);
}

function assertValue(name: string, value: unknown): asserts value is string {
  if (typeof value !== 'string' || value.trim() === '' || /[;{}]/.test(value)) {
    throw new Error(`token "${name}" must be a non-empty CSS value without ; { }`);
  }
}

/** Validates the raw JSON shape so a typo in tokens.json fails the build instead of the UI. */
export function parseTokenSource(raw: unknown): TokenSource {
  if (!isRecord(raw) || !isRecord(raw.themed) || !isRecord(raw.static)) {
    throw new Error('tokens.json must contain "themed" and "static" objects');
  }
  const seen = new Set<string>();
  const themed: TokenSource['themed'] = {};
  for (const [name, entry] of Object.entries(raw.themed)) {
    assertTokenName(name, seen);
    if (!isRecord(entry)) throw new Error(`themed token "${name}" must be an object`);
    const extra = Object.keys(entry).filter((k) => !(THEMES as readonly string[]).includes(k));
    if (extra.length > 0) throw new Error(`themed token "${name}" has unknown themes: ${extra}`);
    const values = {} as Record<Theme, string>;
    for (const theme of THEMES) {
      const value = entry[theme];
      assertValue(`${name}.${theme}`, value);
      values[theme] = value;
    }
    themed[name] = values;
  }
  const statics: TokenSource['static'] = {};
  for (const [name, value] of Object.entries(raw.static)) {
    assertTokenName(name, seen);
    assertValue(name, value);
    statics[name] = value;
  }
  return { themed, static: statics };
}

export function loadTokenSource(path = SOURCE_PATH): TokenSource {
  return parseTokenSource(JSON.parse(readFileSync(path, 'utf8')));
}

function renderCss(source: TokenSource): string {
  const decl = (name: string, value: string) => `  --${name}: ${value};`;
  const themedFor = (theme: Theme) =>
    Object.entries(source.themed).map(([name, values]) => decl(name, values[theme]));
  return [
    `/* ${HEADER} */`,
    ':root {',
    '  color-scheme: light;',
    ...themedFor('light'),
    ...Object.entries(source.static).map(([name, value]) => decl(name, value)),
    '}',
    '',
    '[data-theme="dark"] {',
    '  color-scheme: dark;',
    ...themedFor('dark'),
    '}',
    '',
  ].join('\n');
}

function renderTs(source: TokenSource): string {
  const byTheme = Object.fromEntries(
    THEMES.map((theme) => [
      theme,
      Object.fromEntries(Object.entries(source.themed).map(([n, v]) => [n, v[theme]])),
    ]),
  );
  return [
    `// ${HEADER}`,
    `export const themedTokens = ${JSON.stringify(byTheme)} as const;`,
    `export const staticTokens = ${JSON.stringify(source.static)} as const;`,
    '',
  ].join('\n');
}

async function format(path: string, content: string): Promise<string> {
  const options = (await prettier.resolveConfig(path)) ?? {};
  return prettier.format(content, { ...options, filepath: path });
}

export async function generate(source: TokenSource): Promise<GeneratedFile[]> {
  return Promise.all([
    format(CSS_PATH, renderCss(source)).then((content) => ({ path: CSS_PATH, content })),
    format(TS_PATH, renderTs(source)).then((content) => ({ path: TS_PATH, content })),
  ]);
}

/** Returns the generated files whose committed content differs from a fresh build. */
export function findStale(files: GeneratedFile[]): string[] {
  return files
    .filter((file) => {
      try {
        return readFileSync(file.path, 'utf8') !== file.content;
      } catch {
        return true;
      }
    })
    .map((file) => relative(PACKAGE_DIR, file.path));
}

async function main(argv: string[]): Promise<number> {
  const files = await generate(loadTokenSource());
  if (argv.includes('--check')) {
    const stale = findStale(files);
    if (stale.length > 0) {
      console.error(
        `design-tokens: stale generated files: ${stale.join(', ')}\n` +
          'Run `pnpm --filter @quiz/design-tokens build` and commit the result.',
      );
      return 1;
    }
    console.log('design-tokens: generated files are up to date');
    return 0;
  }
  for (const file of files) {
    mkdirSync(dirname(file.path), { recursive: true });
    writeFileSync(file.path, file.content);
    console.log(`design-tokens: wrote ${relative(PACKAGE_DIR, file.path)}`);
  }
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  process.exitCode = await main(process.argv.slice(2));
}
